// Generated by `kompass schema --write` from the Rust types in engine/core (profile.rs,
// catalogue.rs, route.rs, presets.rs). Do not edit: change the Rust types and regenerate
// (`bun run gen:engine`); `cargo test` fails when this file is stale.

/**
 * A soft preference of the catalogue (`catalogue().preferences`).
 */
export type PrefId = "unpaved" | "paved_smooth" | "paved_rough" | "fine_gravel" | "soft_ground" | "unknown_surface" | "tracktype" | "smoothness" | "track" | "path" | "cycleway_sep" | "cycleway_road" | "residential" | "service" | "minor" | "main" | "quiet" | "speed" | "lanes" | "near_road" | "forest" | "forest_edge" | "water" | "open" | "built" | "climb" | "steep" | "bike_routes" | "mtb_routes" | "access" | "sketchy" | "mtb" | "visibility" | "novel" | "stale" | "familiar";

/**
 * A hard limit of the catalogue (`catalogue().limits`).
 */
export type LimitId = "no_main_roads" | "paved_only" | "no_unknown_surface" | "max_grade" | "max_mtb_scale" | "no_stairs" | "legal_only" | "no_ferries";

/**
 * A soft preference's strength: −100 (avoid) … 0 (neutral) … +100 (seek).
 */
export type Weight = number;

/**
 * A limit's setting: a switch (`true` on, `false` off, as if absent), or a number for limits that
 * take one (`true` there means the catalogue's default number).
 */
export type LimitValue = boolean | number;

/**
 * The clamp of the factor product (`docs/profile.md`): every arc costs between `min_factor` and
 * `max_factor` times its length (plus additive terms). `min_factor` is the A* bound.
 */
export type Bounds = { 
/**
 * 0.3..=1.0, default 0.5. Lower lets bonuses stack further (and searches slow down a little).
 */
min_factor: number, 
/**
 * 2..=100, default 20. The most an allowed way can cost per metre.
 */
max_factor: number, };

/**
 * A routing profile.
 */
export type Profile = { 
/**
 * Display name (presets have one).
 */
name?: string, 
/**
 * The preset this profile was made from (the UI's diff against it; routing ignores it).
 */
base?: string, 
/**
 * Soft preferences. An absent id has no opinion (factor 1); an explicit 0 is the same for
 * routing, but stays on screen.
 */
weights: { [key in PrefId]?: Weight }, 
/**
 * Hard limits.
 */
limits: { [key in LimitId]?: LimitValue }, 
/**
 * The factor clamp; defaults apply when absent.
 */
bounds?: Bounds, };

/**
 * A preset.
 */
export type Preset = { 
/**
 * Stable id (`profile.base` of profiles made from it).
 */
id: string, 
/**
 * One line for the picker.
 */
blurb: string, 
/**
 * The profile; its `name` is the preset's name.
 */
profile: Profile, };

/**
 * A group of the picker.
 */
export type Group = "surface" | "ways" | "traffic" | "landscape" | "terrain" | "signs" | "trail" | "history";

/**
 * What kind of control an entry is.
 */
export type Kind = "soft" | "limit_flag" | "limit_number";

/**
 * A group's text.
 */
export type GroupInfo = { id: Group, label: string, blurb: string, };

/**
 * Where a preference's data comes from, and how much of the region has it.
 */
export type Coverage = { 
/**
 * The attribute the preference rests on (an `edges.parquet` column, or `personal`).
 */
attribute: string, 
/**
 * Share of the region's length where it is mapped, 0..1 (only from a loaded region).
 */
share?: number, 
/**
 * What to know about the data.
 */
note: string, };

/**
 * A soft preference.
 */
export type Preference = { id: PrefId, 
/**
 * Always [`Kind::Soft`].
 */
kind: Kind, group: Group, label: string, 
/**
 * For chips.
 */
short: string, 
/**
 * One line: what it matches.
 */
hint: string, 
/**
 * Words for the slider's ends, when "avoid" / "seek" don't fit.
 */
low_label?: string, high_label?: string, 
/**
 * The weight it starts with when added.
 */
default: number, 
/**
 * Part of the core set every profile shows.
 */
core: boolean, 
/**
 * The factor on a fully matching way at +100 (< 1: cheaper).
 */
max_bonus: number, 
/**
 * The factor on a fully matching way at −100 (> 1: dearer).
 */
max_penalty: number, 
/**
 * Its bonus only counts on ways the rest of the profile finds acceptable (see `docs/profile.md`).
 */
gated: boolean, 
/**
 * Reads the personal layer (no effect without one).
 */
personal: boolean, coverage?: Coverage, };

/**
 * The number of a number limit.
 */
export type NumberRange = { min: number, max: number, step: number, 
/**
 * When the limit is switched on.
 */
default: number, unit: string, };

/**
 * A hard limit.
 */
export type Limit = { id: LimitId, kind: Kind, group: Group, label: string, hint: string, number?: NumberRange, };

/**
 * A bound's range.
 */
export type BoundRange = { min: number, max: number, default: number, };

/**
 * The ranges of [`Bounds`].
 */
export type BoundsInfo = { min_factor: BoundRange, max_factor: BoundRange, };

/**
 * The whole catalogue (`kompass profile catalogue`).
 */
export type Catalogue = { version: number, groups: Array<GroupInfo>, preferences: Array<Preference>, limits: Array<Limit>, 
/**
 * The core set: always on screen, whatever the base.
 */
core: Array<PrefId>, bounds: BoundsInfo, };

/**
 * A coordinate in degrees.
 */
export type Coord = { lon: number, lat: number, };

/**
 * A waypoint of the request.
 */
export type Waypoint = { lon: number, lat: number, name?: string, };

/**
 * Options of a route request.
 */
export type RouteOptions = { 
/**
 * How far from a waypoint its way may be, metres (1..=5000, default 250).
 */
snap_radius_m: number, 
/**
 * Whether to return the geometry (coordinates, elevation, distances per vertex).
 */
geometry: boolean, };

/**
 * An area of a via or avoid zone (reserved: accepted, not used yet).
 */
export type Zone = { "type": "circle", center: Coord, radius_m: number, } | { "type": "polygon", ring: Array<Coord>, };

/**
 * A sketched line to fit the route to (reserved: accepted, not used yet).
 */
export type Sketch = { points: Array<Coord>, };

/**
 * The `route` request.
 */
export type RouteRequest = { 
/**
 * Two or more: start, vias, end.
 */
waypoints: Array<Waypoint>, profile: Profile, 
/**
 * Per leg (waypoint i → i + 1), a profile replacing `profile`; `null` keeps it.
 */
leg_profiles?: Array<Profile | null>, options: RouteOptions, 
/**
 * Reserved: "somewhere through here" zones.
 */
via_zones?: Array<Zone>, 
/**
 * Reserved: zones to stay out of.
 */
avoid_zones?: Array<Zone>, 
/**
 * Reserved: a sketched line.
 */
sketch?: Sketch, };

/**
 * The surface classes of the result (the tag or a safe guess; `unknown` where neither).
 */
export type SurfaceKind = "paved" | "paved_rough" | "compacted" | "gravel" | "soft" | "other" | "unknown";

/**
 * The way types of the route breakdown.
 */
export type WayKind = "main_road" | "country_road" | "residential" | "service" | "track" | "path" | "bike_path" | "bike_path_roadside" | "steps" | "ferry" | "other";

/**
 * A waypoint as snapped.
 */
export type Snapped = { name?: string, 
/**
 * The point on the way.
 */
point: Coord, 
/**
 * Metres from the requested point.
 */
distance_m: number, edge: number, 
/**
 * Position along the edge's geometry, 0..1.
 */
fraction: number, 
/**
 * Set when no allowed way was within the radius and the route starts or ends on an excluded
 * one (it only uses that one edge to get away): what excludes it.
 */
excluded_by?: string, };

/**
 * One preference's part in a cost: its factor (< 1 made it cheaper, > 1 dearer).
 */
export type Reason = { id: PrefId, factor: number, };

/**
 * A stretch of the route with one surface, way type and ridden state.
 */
export type Segment = { 
/**
 * Metres from the route's start.
 */
start_m: number, length_m: number, 
/**
 * `[first, end)` indices into the route's `arcs`.
 */
arcs: [number, number], 
/**
 * `[first, last]` indices into the geometry's vertices (empty geometry: 0, 0).
 */
vertices: [number, number], surface: SurfaceKind, way: WayKind, 
/**
 * Ridden before (only with a personal layer).
 */
ridden?: boolean, 
/**
 * The mean cost factor per metre (the clamp included).
 */
factor: number, 
/**
 * Additive cost (climbing, barriers, steps, …) in metres.
 */
extra_m: number, 
/**
 * Why this way: the strongest preferences here (length-weighted geometric means), at most 3,
 * strongest first.
 */
why: Array<Reason>, };

/**
 * One leg (waypoint `i` → `i + 1`).
 */
export type Leg = { distance_m: number, ascent_m: number, descent_m: number, duration_s: number, 
/**
 * The leg's cost under its profile (metres-equivalent).
 */
cost: number, 
/**
 * `[first, end)` into `arcs` and `segments`.
 */
arcs: [number, number], segments: [number, number], 
/**
 * Nodes the search settled.
 */
settled: number, };

/**
 * The totals.
 */
export type Summary = { distance_m: number, 
/**
 * Climbing beyond the noise deadband (see `docs/profile.md`).
 */
ascent_m: number, descent_m: number, 
/**
 * A rough riding time from a speed model by surface and grade.
 */
duration_s: number, cost: number, 
/**
 * Shares of the length, 0..1.
 */
unpaved_share: number, unknown_surface_share: number, main_road_m: number, 
/**
 * Never-ridden share (only with a personal layer).
 */
new_share?: number, };

/**
 * A length per key.
 */
export type Part<K> = { key: K, length_m: number, share: number, };

/**
 * Ridden vs. new.
 */
export type RiddenParts = { new_m: number, ridden_m: number, new_share: number, };

/**
 * The breakdowns, longest first.
 */
export type Breakdown = { surface: Array<Part<SurfaceKind>>, way: Array<Part<WayKind>>, ridden?: RiddenParts, };

/**
 * The line: coordinates, and per vertex the distance from the start and the elevation.
 */
export type RouteGeometry = { 
/**
 * `[lon, lat]`, 1e-6 degrees.
 */
coordinates: Array<[number, number]>, 
/**
 * Metres from the start.
 */
distance_m: Array<number>, 
/**
 * Metres (from the end nodes of each edge, linear in between); absent where the build has no
 * elevations.
 */
elevation_m?: Array<number>, };

/**
 * The `route` result.
 */
export type RouteResult = { summary: Summary, breakdown: Breakdown, waypoints: Array<Snapped>, legs: Array<Leg>, segments: Array<Segment>, 
/**
 * The route as arcs (`edge << 1 | reverse`; the first and last are partial).
 */
arcs: Array<number>, 
/**
 * Per arc, the index of its first vertex in the geometry.
 */
arc_vertex: Array<number>, geometry?: RouteGeometry, 
/**
 * What to know (ignored reserved fields, waypoints on excluded ways).
 */
notes: Array<string>, };

/**
 * What went wrong.
 */
export type ErrorCode = "invalid_request" | "invalid_profile" | "no_way_near" | "excluded" | "no_route";

/**
 * A failed query.
 */
export type RouteError = { code: ErrorCode, message: string, waypoint?: number, leg?: number, };

/**
 * The `diff` request: two routes' arcs (`RouteResult::arcs`).
 */
export type DiffRequest = { a: Array<number>, b: Array<number>, };

/**
 * A stretch of one route.
 */
export type Span = { 
/**
 * `[first, end)` into that route's arcs (empty: the other route detours here).
 */
arcs: [number, number], 
/**
 * Metres from that route's start (edges counted in full).
 */
start_m: number, length_m: number, };

/**
 * Where two routes part and meet again.
 */
export type Stretch = { a: Span, b: Span, };

/**
 * The `diff` result.
 */
export type RouteDiff = { stretches: Array<Stretch>, 
/**
 * Length both share (by `a`), and only one has.
 */
shared_m: number, a_only_m: number, b_only_m: number, };

/**
 * One arc's cost, explained.
 */
export type ArcExplanation = { arc: number, length_m: number, 
/**
 * Absent when excluded.
 */
cost?: number, factor: number, 
/**
 * How much of the gated bonuses counted (0..1).
 */
gate: number, climb_m: number, penalty_m: number, 
/**
 * Every preference whose factor is not 1 here.
 */
reasons: Array<Reason>, excluded_by?: string, };
